(()=>{
const U=id=>`https://unsplash.com/photos/${id}/download?force=true&w=1600`;
const V={
 hero:U('Uu1CtKngEXY'),
 biodiversity:U('Uu1CtKngEXY'),
 reef:U('UtHxGSh8r5o'),
 coast:U('WYBOow2ekw8'),
 guardian:U('-GezxTGRL5U'),
 fishing:U('XEtFmDMUNB0'),
 field:U('vmzFY0tS8T0'),
 educator:U('6c86TCPmNRQ'),
 family:U('0iqkntLw93A')
};
const v=(k)=>V[k]||V.hero;
const cat=(l)=>{let s=(l?.slug||'').toLowerCase();if(/pollution|plastic/.test(s))return'guardian';if(/fishing|bycatch|consumption/.test(s))return'fishing';if(/coast|water-safety|accessible/.test(s))return'coast';if(/citizen|blue-action|responsible|protected|climate/.test(s))return'field';if(/food|ecosystem|posidonia/.test(s))return'reef';return'biodiversity'};
const catLabel=l=>({reef:'Οικοσύστημα',biodiversity:'Θαλάσσια ζωή',guardian:'Ρύπανση',fishing:'Αλιεία',coast:'Ακτή & πρόσβαση',field:'Δράση & κοινότητα'}[cat(l)]||'Θάλασσα');
const pct=()=>S.lessons.length?Math.round(Object.values(S.progress).reduce((a,x)=>a+(+x.mastery||0),0)/(S.lessons.length*100)*100):0;
const done=()=>Object.values(S.progress).filter(x=>x.completed).length;
const preview=()=>isDemo()?`<div class="ba-preview"><b>Προεπισκόπηση ρόλου:</b> ${esc(viewerLabel())}. Βλέπεις την πλήρη εμπειρία όπως θα την έχει ο χρήστης· οι ενέργειες προεπισκόπησης δεν αλλάζουν τα πραγματικά δεδομένα.</div>`:'';
const stat=(ico,val,label)=>`<article class="card ba-stat"><span class="ico">${ico}</span><div><strong>${val}</strong><small>${label}</small></div></article>`;
const hero=(asset,kicker,title,copy,side='')=>`<section class="ba-hero" style="background-image:url('${v(asset)}')"><div><span class="tag">${kicker}</span><h1>${title}</h1><p>${copy}</p></div>${side?`<div class="ba-hero-side">${side}</div>`:''}</section>`;
const sec=(title,copy='',action='')=>`<div class="ba-section"><div><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>${action}</div>`;
const contentFor=l=>l?.[S.prefs.level+'_content']||l?.standard_content||{};
const points=c=>Array.isArray(c?.key_points)&&c.key_points.length?c.key_points:["Παρατήρησε προσεκτικά το θαλάσσιο περιβάλλον.","Σύνδεσε τη γνώση με μια πραγματική επιλογή.","Μοιράσου αυτό που έμαθες με την ομάδα σου."];
const lessonProgress=l=>+S.progress[l.id]?.mastery||0;

function upgradeShell(){
  const dr=$('#demoRole');if(dr){dr.setAttribute('aria-label','Προεπισκόπηση εμπειρίας ρόλου');let labels={'':'Κανονική διαχείριση','student':'Προβολή · Μαθητής','beneficiary':'Προβολή · Ωφελούμενος','educator':'Προβολή · Εκπαιδευτικός','caregiver':'Προβολή · Οικογένεια'};[...dr.options].forEach(o=>o.textContent=labels[o.value]||o.textContent)}
  document.querySelectorAll('.proof span').forEach(x=>{if(/10 ενότητες/.test(x.textContent))x.textContent='18 ενότητες'});
  const art=document.querySelector('.auth .art');if(art)art.style.backgroundImage=`url('${v('hero')}')`;
  ensureGameDialog();
}

const proMenus={
 learner:[['home','⌂','Αρχική'],['learn','▣','Μαθαίνω'],['games','🎮','Παιχνίδια'],['classroom','👥','Η τάξη μου'],['assistant','◉','Θαλάσσιος Βοηθός'],['field','✦','Δράσεις'],['community','☁','Κοινότητα'],['progress','▥','Η πρόοδός μου']],
 educator:[['home','⌂','Επισκόπηση'],['learn','▣','Βιβλιοθήκη'],['classroom','👥','Τάξεις'],['games','🎮','Δραστηριότητες'],['field','✦','Δράσεις'],['community','☁','Κοινότητα'],['progress','▥','Αναφορές']],
 caregiver:[['home','⌂','Επισκόπηση'],['progress','▥','Πρόοδος'],['learn','▣','Τι μαθαίνουμε'],['field','✦','Δράσεις'],['community','☁','Κοινότητα']],
 org_admin:[['home','⌂','Οργανισμός'],['organization','⚙','Διαχείριση'],['learn','▣','Περιεχόμενο'],['games','🎮','Δραστηριότητες'],['progress','▥','Analytics'],['field','✦','Δράσεις'],['community','☁','Κοινότητα']]
};
renderNav=function(){let items=proMenus[role()]||proMenus.learner;$('#nav').innerHTML=items.map(x=>`<button data-v="${x[0]}"><span>${x[1]}</span><span>${x[2]}</span></button>`).join('');$$('[data-v]').forEach(b=>b.onclick=()=>go(b.dataset.v))};
const baseShowApp=showApp;showApp=function(){baseShowApp();$('#ur').textContent=(isDemo()?'ΠΡΟΕΠΙΣΚΟΠΗΣΗ · ':'')+viewerLabel()};
pending=preview;
setDemo=function(type){if(!isAdmin())return;S.demoRole=type||null;S.progress=S.demoRole?makeDemoProgress(S.demoRole):JSON.parse(JSON.stringify(S.realProgress||{}));showApp();renderNav();go('home');toast(S.demoRole?'Άνοιξε προεπισκόπηση '+viewerLabel()+'.':'Επέστρεψες στη διαχείριση BlueAbility.')};
go=function(view){S.view=view;$$('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.v===view));let map={home,learn,games,assistant,field,progress,classroom,organization,community};(map[view]||home)();$('#side').classList.remove('open')};

cards=function(arr){return arr.map(l=>{let p=lessonProgress(l);return`<article class="card ba-visual-card lesson" data-cat="${cat(l)}"><div class="ba-thumb" style="background-image:url('${v(cat(l))}')"></div><div class="ba-card-body"><div style="display:flex;justify-content:space-between;gap:8px"><span class="tag">Ενότητα ${String(l.position).padStart(2,'0')}</span><small class="muted">${catLabel(l)}</small></div><h3>${esc(l.title)}</h3><p>${esc(l.summary||'')}</p><div class="ba-progress"><i style="width:${p}%"></i></div><div class="ba-card-foot"><small class="muted">${p?p+'% πρόοδος':'Νέα ενότητα'}</small><button class="btn q" data-l="${l.id}">${p?'Συνέχισε':'Ξεκίνα'} →</button></div></div></article>`}).join('')||'<div class="card ba-empty"><span class="ico">🌊</span><p>Δεν υπάρχουν διαθέσιμες ενότητες.</p></div>'};

home=async function(){
 if(role()==='org_admin'&&!isDemo())return organization();
 if(role()==='educator')return educatorHome();
 if(role()==='caregiver')return caregiverHome();
 let first=S.lessons.find(l=>!S.progress[l.id]?.completed)||S.lessons[0];let p=pct();
 let requests='';
 if(!isDemo()&&role()==='learner'){
   let{data:r}=await sb.from('caregiver_links').select('caregiver_id,created_at').eq('learner_id',S.user.id).is('approved_at',null);
   if(r?.length)requests=`<article class="card ba-panel"><h3>Αίτημα σύνδεσης οικογένειας</h3><p class="muted">Ένας φροντιστής ζήτησε να βλέπει την πρόοδό σου. Εσύ αποφασίζεις.</p>${r.map(x=>`<button class="btn p" data-care-approve="${x.caregiver_id}">Έγκριση σύνδεσης</button>`).join(' ')}</article>`;
 }
 $('#main').innerHTML=`${preview()}${hero('hero','Μαθαίνω · Συμμετέχω · Προστατεύω',`Καλωσόρισες, ${esc(viewerName().split(' ')[0]||'')}.`,`Κάθε μικρή γνώση μπορεί να γίνει μια πραγματική πράξη για μια καθαρότερη, πιο προσβάσιμη και πιο ζωντανή θάλασσα.`,`<div class="ba-glass"><small>Η πρόοδός σου</small><strong>${p}%</strong><div class="ba-progress"><i style="width:${p}%"></i></div></div><div class="ba-glass"><small>Επόμενη διαδρομή</small><strong style="font-size:1rem">${esc(first?.title||'Εξερεύνηση')}</strong><button class="btn p" data-l="${first?.id||''}" style="margin-top:9px">Συνέχισε →</button></div>`) }
 <div class="ba-stats">${stat('📘',done(),'ολοκληρωμένες ενότητες')}${stat('⭐',S.badges.length,'σήματα')}${stat('🎮','6','διαδραστικά παιχνίδια')}${stat('🌱',S.events.length,'δράσεις')}</div>
 ${requests}
 ${sec('Συνέχισε από εκεί που έμεινες','Μικρά βήματα, χωρίς χρονική πίεση.','<button class="btn q" data-go="learn">Όλες οι ενότητες →</button>')}
 <div class="ba-grid ba-grid-3">${cards(S.lessons.slice(0,3))}</div>
 ${sec('Δημοφιλείς εμπειρίες','Παίξε, παρατήρησε και δοκίμασε στην πράξη.','<button class="btn q" data-go="games">Όλα τα παιχνίδια →</button>')}
 <div class="ba-grid ba-grid-3"><article class="card ba-visual-card"><div class="ba-thumb" style="background-image:url('${v('guardian')}')"></div><div class="ba-card-body"><span class="tag">Παιχνίδι</span><h3>Ο Φύλακας της Θάλασσας</h3><p>Εντόπισε κινδύνους και πάρε σωστές αποφάσεις.</p><button class="btn p" data-play="guardian">Παίξε τώρα</button></div></article><article class="card ba-visual-card"><div class="ba-thumb" style="background-image:url('${v('field')}')"></div><div class="ba-card-body"><span class="tag">Στο πεδίο</span><h3>Καθαρή ακτή, μαζί</h3><p>Η μάθηση γίνεται συμμετοχή στην κοινότητα.</p><button class="btn q" data-go="field">Δες δράσεις</button></div></article><article class="card ba-visual-card"><div class="ba-thumb" style="background-image:url('${v('reef')}')"></div><div class="ba-card-body"><span class="tag">Βοηθός</span><h3>Έχεις απορία;</h3><p>Ρώτησε για έννοιες από τις 18 εκπαιδευτικές ενότητες.</p><button class="btn q" data-go="assistant">Ρώτησε</button></div></article></div>`;
 bindPro();
 $$('[data-care-approve]').forEach(b=>b.onclick=async()=>{let{error}=await sb.from('caregiver_links').update({approved_at:new Date().toISOString()}).eq('learner_id',S.user.id).eq('caregiver_id',b.dataset.careApprove);if(error)toast(error.message);else{toast('Η σύνδεση εγκρίθηκε.');home()}});
};

learn=function(){
 $('#main').innerHTML=`${preview()}${hero('biodiversity','18 θεματικές διαδρομές','Ανακάλυψε τον κόσμο της θάλασσας.','Μάθημα, οπτική παρατήρηση, ακρόαση, δραστηριότητα, κουίζ, συζήτηση και πραγματική δράση — με τρία επίπεδα γλώσσας.','<div class="ba-glass"><small>Επίπεδο περιεχομένου</small><strong style="font-size:1rem">'+({easy:'Απλό',standard:'Κανονικό',advanced:'Προχωρημένο'}[S.prefs.level]||'Κανονικό')+'</strong></div>')}
 <div class="ba-filterbar"><button class="ba-chip on" data-filter="all">Όλα</button><button class="ba-chip" data-filter="reef">Οικοσυστήματα</button><button class="ba-chip" data-filter="biodiversity">Θαλάσσια ζωή</button><button class="ba-chip" data-filter="guardian">Ρύπανση</button><button class="ba-chip" data-filter="fishing">Αλιεία</button><button class="ba-chip" data-filter="coast">Ακτή & πρόσβαση</button><button class="ba-chip" data-filter="field">Δράση</button></div>
 <div class="lessons ba-grid ba-grid-3">${cards(S.lessons)}</div>`;
 bindLessons();bindPro();$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>x.classList.toggle('on',x===b));$$('.lesson').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.cat!==b.dataset.filter)})
};

steps=function(l){let c=contentFor(l),ps=points(c),quiz=c.quiz||null,img=v(cat(l));return[
 ['Μάθημα',`<div class="ba-lesson-hero" style="background-image:url('${img}')"><span>${esc(l.title)}</span></div><h3>${esc(l.title)}</h3><p>${esc(c.text||l.summary||'')}</p><div class="ba-points">${ps.map(x=>`<div class="ba-point">✓ ${esc(x)}</div>`).join('')}</div>`],
 ['Βλέπω',`<div class="ba-lesson-hero" style="background-image:url('${img}')"><span>Παρατήρησε πριν απαντήσεις</span></div><h3>Τι βλέπεις;</h3><p>Κοίτα την εικόνα σαν ερευνητής. Παρατήρησε οργανισμούς, ανθρώπινες δραστηριότητες, πιθανούς κινδύνους και στοιχεία που δείχνουν ένα υγιές περιβάλλον.</p><div class="ba-activity"><b>Αποστολή παρατήρησης</b><p>${esc(c.activity||'Βρες τρία στοιχεία στην εικόνα και εξήγησε πώς συνδέονται με το θέμα.')}</p></div>`],
 ['Ακούω',`<h3>Άκουσε το μάθημα</h3><p>${esc(c.text||l.summary||'')}</p><div class="ba-activity"><b>Προσβάσιμη ακρόαση</b><p>Μπορείς να ακούσεις το κείμενο όσες φορές χρειάζεσαι, χωρίς χρονικό περιορισμό.</p><button class="btn p" id="speak">▶ Ακρόαση κειμένου</button></div>`],
 ['Δραστηριότητα',`<h3>Δοκίμασέ το</h3><div class="ba-activity"><p>${esc(c.activity||'Σύνδεσε το θέμα με μια παρατήρηση ή εμπειρία από την καθημερινότητά σου.')}</p></div><p><b>Η δική σου σημείωση</b></p><textarea class="ba-note" id="lessonNote" placeholder="Γράψε ή υπαγόρευσε τι παρατήρησες…"></textarea><button class="btn q" id="saveNote" style="margin-top:9px">Αποθήκευση στο portfolio</button>`],
 ['Κουίζ',quiz?`<h3>${esc(quiz.q)}</h3><div class="ba-quiz">${(quiz.options||[]).map((x,i)=>`<button class="ba-option" data-quiz="${i}">${esc(x)}</button>`).join('')}</div><div id="quizFeedback"></div>`:`<h3>Γρήγορος έλεγχος</h3><p>Εξήγησε με δικά σου λόγια το βασικό μήνυμα της ενότητας.</p>`],
 ['Συζητώ',`<h3>Σκέψου και μοιράσου</h3><div class="ba-activity"><p>${esc(c.reflection||'Πώς συνδέεται αυτή η γνώση με τη ζωή σου, την τάξη ή την κοινότητά σου;')}</p></div><p class="muted">Δεν υπάρχει μία «τέλεια» απάντηση. Στόχος είναι να συνδέσεις τη γνώση με τη δική σου εμπειρία.</p>`],
 ['Δρω',`<h3>Από τη γνώση στη δράση</h3><div class="ba-activity"><b>Μικρό επόμενο βήμα</b><p>${esc(c.action||'Διάλεξε μια μικρή, ασφαλή πράξη που μπορείς να κάνεις για τη θάλασσα ή την κοινότητά σου.')}</p></div><p>Όταν νιώσεις έτοιμος/η, ολοκλήρωσε τη διαδρομή. Μπορείς πάντα να επιστρέψεις και να την επαναλάβεις.</p><button class="btn p" id="complete">Ολοκλήρωση ενότητας ✓</button>`]
]};
const coreOpen=openLesson;
openLesson=function(id){S.cur=S.lessons.find(x=>x.id===id);if(!S.cur)return;S.step=Math.min(S.progress[id]?.last_step||0,6);$('#lt').textContent=S.cur.title;draw();$('#lesson').showModal()};
async function saveStep(){if(isDemo()||role()!=='learner'||!S.user||!S.cur)return;let mastery=Math.min(95,Math.max(+S.progress[S.cur.id]?.mastery||0,Math.round((S.step+1)/7*100)));let payload={learner_id:S.user.id,lesson_id:S.cur.id,mastery,completed:false,last_step:S.step,last_seen_at:new Date().toISOString()};await sb.from('lesson_progress').upsert(payload,{onConflict:'learner_id,lesson_id'});S.progress[S.cur.id]={...(S.progress[S.cur.id]||{}),...payload}}
draw=function(){let a=steps(S.cur);$('#steps').innerHTML=a.map((x,i)=>`<button class="${i===S.step?'on':''}" data-step="${i}">${i+1}. ${x[0]}</button>`).join('');$('#copy').innerHTML=a[S.step][1];$('#prev').disabled=S.step===0;$('#next').disabled=S.step===6;$$('[data-step]').forEach(b=>b.onclick=()=>{S.step=+b.dataset.step;draw();saveStep()});$('#speak')?.addEventListener('click',()=>{speechSynthesis.cancel();let u=new SpeechSynthesisUtterance($('#copy').innerText);u.lang='el-GR';speechSynthesis.speak(u)});$('#saveNote')?.addEventListener('click',saveLessonNote);let c=contentFor(S.cur),q=c.quiz;$$('[data-quiz]').forEach(b=>b.onclick=()=>{let i=+b.dataset.quiz,good=i===+q.answer;$$('[data-quiz]').forEach(x=>x.disabled=true);b.classList.add(good?'good':'bad');if(!good)$$(`[data-quiz="${q.answer}"]`).forEach(x=>x.classList.add('good'));$('#quizFeedback').innerHTML=`<div class="ba-feedback"><b>${good?'Μπράβο!':'Δοκίμασε να το σκεφτείς ξανά.'}</b><br>${esc(q.explanation||'')}</div>`});$('#complete')?.addEventListener('click',complete);$('#prev').onclick=()=>{if(S.step){S.step--;draw();saveStep()}};$('#next').onclick=()=>{if(S.step<6){S.step++;draw();saveStep()}}};
async function saveLessonNote(){let text=$('#lessonNote')?.value.trim();if(!text)return toast('Γράψε πρώτα μια μικρή σημείωση.');if(isDemo())return toast('Η σημείωση έμεινε στην προεπισκόπηση.');let{error}=await sb.from('portfolio_items').insert({user_id:S.user.id,title:'Σημείωση · '+S.cur.title,description:text,item_type:'reflection',metadata:{lesson_id:S.cur.id,lesson_slug:S.cur.slug}});toast(error?error.message:'Η σημείωση αποθηκεύτηκε στο portfolio σου.')}
complete=async function(){if(isDemo()){S.progress[S.cur.id]={mastery:100,completed:true,last_step:6};$('#lesson').close();toast('Η ενότητα ολοκληρώθηκε στην προεπισκόπηση.');return go('progress')}let{error}=await sb.from('lesson_progress').upsert({learner_id:S.user.id,lesson_id:S.cur.id,mastery:100,completed:true,last_step:6,last_seen_at:new Date().toISOString(),completed_at:new Date().toISOString()},{onConflict:'learner_id,lesson_id'});if(error)return toast(error.message);S.progress[S.cur.id]={mastery:100,completed:true,last_step:6};$('#lesson').close();toast('Η πρόοδός σου αποθηκεύτηκε.');go('progress')};

const GAME_DEFS=[
 {slug:'guardian',title:'Ο Φύλακας της Θάλασσας',copy:'Εντόπισε απειλές και διάλεξε την ασφαλέστερη αντίδραση.',asset:'guardian',qs:[['Βλέπεις μπερδεμένη πετονιά πάνω στα βράχια. Τι κάνεις;',['Την αφήνω εκεί','Τη συλλέγω μόνο αν είναι ασφαλές, με κατάλληλη προστασία','Τη ρίχνω στο νερό'],1,'Αν είναι ασφαλές, συλλέγουμε με προστασία. Αιχμηρά ή επικίνδυνα αντικείμενα τα χειρίζεται υπεύθυνος.'],['Ένα πλαστικό μπουκάλι κινείται προς τη θάλασσα.',['Το απομακρύνω και το βάζω στον κατάλληλο κάδο','Το κλωτσάω πιο μέσα','Δεν έχει σημασία'],0,'Η πρόληψη πριν το απόρριμμα φτάσει στη θάλασσα έχει μεγάλη αξία.'],['Βλέπεις άγνωστο δοχείο με υγρό.',['Το ανοίγω για να δω','Το μυρίζω','Δεν το αγγίζω και ενημερώνω υπεύθυνο'],2,'Δεν αγγίζουμε άγνωστες ουσίες ή επικίνδυνα απορρίμματα.']]},
 {slug:'right-net',title:'Το Σωστό Δίχτυ',copy:'Πάρε αποφάσεις που μειώνουν τα ανεπιθύμητα αλιεύματα.',asset:'fishing',qs:[['Πιάνεται κατά λάθος προστατευόμενο ή άγνωστο είδος.',['Ακολουθώ τις επίσημες οδηγίες ασφαλούς χειρισμού/απελευθέρωσης','Το κρατάω πάντα','Το φωτογραφίζω για ώρα'],0,'Η σωστή αντίδραση εξαρτάται από το είδος και τις επίσημες οδηγίες.'],['Ένα εργαλείο πιάνει συχνά πολύ μικρά άτομα.',['Δεν αλλάζω τίποτα','Εξετάζω πιο επιλεκτική πρακτική/εργαλείο σύμφωνα με τους κανόνες','Αυξάνω την προσπάθεια'],1,'Η επιλεκτικότητα βοηθά στη μείωση ανεπιθύμητων συλλήψεων.'],['Για βιώσιμη αλιεία χρειάζονται:',['Μόνο περισσότερα ψάρια σήμερα','Κανόνες, δεδομένα και συνεργασία','Καμία καταγραφή'],1,'Η βιωσιμότητα απαιτεί διαχείριση, παρακολούθηση και συνεργασία.']]},
 {slug:'ecosystem',title:'Χτίσε ένα Υγιές Οικοσύστημα',copy:'Σύνδεσε οργανισμούς, οικότοπους και ανθρώπινες επιλογές.',asset:'reef',qs:[['Ποιο αποτελεί βάση πολλών θαλάσσιων τροφικών δικτύων;',['Παραγωγοί όπως φυτοπλαγκτόν και φυτά','Πλαστικά','Μόνο μεγάλοι θηρευτές'],0,'Οι παραγωγοί μετατρέπουν την ενέργεια σε βιομάζα και στηρίζουν πολλούς τροφικούς δρόμους.'],['Αν χαθεί ένας σημαντικός οικότοπος:',['Δεν αλλάζει τίποτα','Μπορεί να επηρεαστούν πολλά είδη','Όλα τα είδη αυξάνονται'],1,'Οι οικότοποι προσφέρουν τροφή, καταφύγιο και χώρο αναπαραγωγής.'],['Ποια επιλογή βοηθά περισσότερο;',['Παρατήρηση χωρίς ενόχληση','Μετακίνηση οργανισμών για φωτογραφία','Απόρριψη τροφών στη θάλασσα'],0,'Η υπεύθυνη παρατήρηση μειώνει την πίεση στους οργανισμούς.']]},
 {slug:'fish-journey',title:'Το Ταξίδι του Ψαριού',copy:'Ακολούθησε τη διαδρομή από τη θάλασσα μέχρι το τραπέζι.',asset:'fishing',qs:[['Ποια πληροφορία βοηθά μια υπεύθυνη επιλογή;',['Προέλευση και τρόπος αλιείας','Μόνο το χρώμα της συσκευασίας','Τίποτα'],0,'Η ιχνηλασιμότητα και η πληροφόρηση βοηθούν τον καταναλωτή.'],['Τι μειώνει τη σπατάλη;',['Σχεδιασμός ποσότητας και σωστή συντήρηση','Αγορά χωρίς ανάγκη','Απόρριψη βρώσιμης τροφής'],0,'Η πρόληψη της σπατάλης ξεκινά από τον προγραμματισμό.'],['Η βιώσιμη κατανάλωση είναι:',['Μία μόνο τέλεια επιλογή','Συνδυασμός ενημέρωσης, εποχικότητας και μείωσης σπατάλης','Πάντα το μεγαλύτερο ψάρι'],1,'Οι υπεύθυνες επιλογές βασίζονται σε περισσότερους από έναν παράγοντες.']]},
 {slug:'clean-coast',title:'Καθαρή Ακτή',copy:'Ταξινόμησε απορρίμματα και δούλεψε με ασφάλεια.',asset:'coast',qs:[['Στον καθαρισμό βρίσκεις σπασμένο γυαλί.',['Το πιάνω με γυμνά χέρια','Ενημερώνω υπεύθυνο και χρησιμοποιείται κατάλληλος εξοπλισμός','Το θάβω'],1,'Η ασφάλεια της ομάδας προηγείται.'],['Πριν ξεκινήσει δράση καθαρισμού:',['Ορίζουμε ρόλους, όρια και κανόνες ασφάλειας','Τρέχουμε παντού','Δεν χρειάζεται σχέδιο'],0,'Η προετοιμασία κάνει τη δράση ασφαλή και προσβάσιμη.'],['Μετά τη συλλογή:',['Καταγράφουμε και διαχωρίζουμε όπου είναι εφικτό','Τα αφήνουμε όλα στην άμμο','Τα ξαναρίχνουμε στο νερό'],0,'Η καταγραφή βοηθά να καταλάβουμε τις πηγές απορριμμάτων και να δράσουμε προληπτικά.']]},
 {slug:'species',title:'Γνώρισε τα Είδη της Μεσσηνίας',copy:'Παρατήρησε χαρακτηριστικά και μάθε να αναγνωρίζεις χωρίς να ενοχλείς.',asset:'biodiversity',qs:[['Πώς αναγνωρίζουμε υπεύθυνα ένα είδος;',['Με φωτογραφία και παρατήρηση χαρακτηριστικών','Πιάνοντάς το πάντα','Με βάση μόνο το μέγεθος'],0,'Χρώμα, σχήμα, κίνηση, οικότοπος και φωτογραφίες βοηθούν στην αναγνώριση.'],['Η Ποσειδωνία είναι:',['Θαλάσσιο ανθοφόρο φυτό','Ψάρι','Πλαστικό'],0,'Η Posidonia oceanica είναι θαλάσσιο ανθοφόρο φυτό της Μεσογείου.'],['Όταν βλέπουμε θαλάσσια χελώνα:',['Κρατάμε απόσταση και δεν την ενοχλούμε','Της δίνουμε φαγητό','Την αγγίζουμε'],0,'Η παρατήρηση από απόσταση μειώνει την όχληση.']]}
];
function ensureGameDialog(){if($('#gameModal'))return;let d=document.createElement('dialog');d.id='gameModal';d.className='ba-game-modal';d.innerHTML='<div id="gameMount"></div>';document.body.appendChild(d)}
games=function(){$('#main').innerHTML=`${preview()}${hero('reef','Μάθε παίζοντας','6 παιχνίδια. Όλα ενεργά.','Χωρίς υποχρεωτικό χρονόμετρο ή κατάταξη. Παίρνεις άμεσο feedback, μπορείς να επαναλάβεις και το αποτέλεσμα αποθηκεύεται στον λογαριασμό σου.','<div class="ba-glass"><small>Παιχνίδια</small><strong>6 / 6</strong></div><div class="ba-glass"><small>Ρυθμός</small><strong style="font-size:1rem">Χωρίς πίεση</strong></div>')}${sec('Διάλεξε αποστολή','Κάθε παιχνίδι συνδέεται με πραγματικό εκπαιδευτικό στόχο.')}<div class="ba-games">${GAME_DEFS.map((g,i)=>`<article class="card ba-game-card"><div class="ba-thumb" style="background-image:url('${v(g.asset)}')"></div><div class="ba-card-body"><span class="tag">Αποστολή ${i+1}</span><h3>${g.title}</h3><p>${g.copy}</p><button class="btn p" data-play="${g.slug}">Παίξε τώρα →</button></div></article>`).join('')}</div>`;bindPro()};
function startGame(slug){let g=GAME_DEFS.find(x=>x.slug===slug);if(!g)return;ensureGameDialog();let state={i:0,score:0,answers:[]};const d=$('#gameModal'),m=$('#gameMount');const drawGame=()=>{let q=g.qs[state.i];m.innerHTML=`<div class="ba-game-visual" style="background-image:url('${v(g.asset)}')"><div class="ba-game-title"><small>Ερώτηση ${state.i+1} από ${g.qs.length}</small><h2>${g.title}</h2></div></div><div class="ba-game-body"><div class="ba-game-score"><span>Σκορ <b>${state.score}</b></span><button class="btn q" id="gameClose">Κλείσιμο</button></div><div class="ba-game-q">${esc(q[0])}</div><div class="ba-quiz">${q[1].map((x,i)=>`<button class="ba-option" data-ga="${i}">${esc(x)}</button>`).join('')}</div><div id="gfb"></div></div>`;$('#gameClose').onclick=()=>d.close();$$('[data-ga]').forEach(b=>b.onclick=()=>{let a=+b.dataset.ga,good=a===q[2];state.answers.push(a);if(good)state.score++;$$('[data-ga]').forEach(x=>x.disabled=true);b.classList.add(good?'good':'bad');if(!good)$$(`[data-ga="${q[2]}"]`).forEach(x=>x.classList.add('good'));$('#gfb').innerHTML=`<div class="ba-feedback">${good?'<b>Σωστά!</b>':'<b>Καλή προσπάθεια.</b>'}<br>${esc(q[3])}</div><button class="btn p" id="gnext" style="margin-top:12px">${state.i===g.qs.length-1?'Ολοκλήρωση':'Επόμενη →'}</button>`;$('#gnext').onclick=async()=>{if(state.i<g.qs.length-1){state.i++;drawGame()}else{await finishGame(g,state);d.close();games()}}})};drawGame();d.showModal()}
async function finishGame(g,state){let score=Math.round(state.score/g.qs.length*100);if(!isDemo()&&role()==='learner'){let{error}=await sb.from('game_results').insert({learner_id:S.user.id,game_slug:g.slug,score,metadata:{answers:state.answers,total:g.qs.length}});if(error)return toast(error.message)}toast(`Ολοκλήρωσες το παιχνίδι με ${score}%!`)}

assistant=function(){$('#main').innerHTML=`${preview()}${hero('biodiversity','Θαλάσσιος Βοηθός','Ρώτα. Δες. Σύνδεσε.','Ο βοηθός χρησιμοποιεί το εκπαιδευτικό υλικό του BlueAbility για να εξηγεί έννοιες με απλά λόγια και να προτείνει σχετική ενότητα ή δράση.','<div class="ba-glass"><small>Γνώση</small><strong>18 ενότητες</strong></div><div class="ba-glass"><small>Γλώσσα</small><strong style="font-size:1rem">Προσαρμοσμένη</strong></div>')}<div class="ba-chat-shell" style="margin-top:18px"><article class="card ba-chat-guide"><div class="ba-thumb" style="background-image:url('${v('reef')}')"></div><h3>Δοκίμασε μια ερώτηση</h3><button class="btn q ask">Τι είναι η Ποσειδωνία;</button><button class="btn q ask">Γιατί τα πλαστικά είναι πρόβλημα;</button><button class="btn q ask">Πώς προστατεύω μια θαλάσσια χελώνα;</button><button class="btn q ask">Τι σημαίνει βιώσιμη αλιεία;</button></article><article class="card chatbox"><div class="log" id="log"><div class="msg bot">Γεια! Είμαι ο Θαλάσσιος Βοηθός του BlueAbility. Ρώτησέ με κάτι από τις ενότητες ή ζήτησέ μου μια ιδέα δράσης.</div></div><form id="chat"><input name="q" placeholder="Γράψε μια ερώτηση…" required><button aria-label="Αποστολή">↑</button></form></article></div>`;let ask=async q=>{let ans=answerFromLessons(q),log=$('#log');log.insertAdjacentHTML('beforeend',`<div class="msg usr">${esc(q)}</div><div class="msg bot">${ans}</div>`);log.scrollTop=log.scrollHeight;if(!isDemo()){let{data:c}=await sb.from('assistant_conversations').insert({user_id:S.user.id,title:q.slice(0,60)}).select('id').single();if(c)await sb.from('assistant_messages').insert([{conversation_id:c.id,sender:'user',content:q},{conversation_id:c.id,sender:'assistant',content:log.lastElementChild.innerText}])}};$$('.ask').forEach(b=>b.onclick=()=>ask(b.textContent));$('#chat').onsubmit=e=>{e.preventDefault();let q=new FormData(e.target).get('q');ask(q);e.target.reset()}};
function answerFromLessons(q){let s=q.toLowerCase(),terms=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/\W+/).filter(x=>x.length>3),best=null,bestN=-1;for(let l of S.lessons){let c=contentFor(l),hay=(l.title+' '+l.summary+' '+(c.text||'')+' '+points(c).join(' ')).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let n=terms.reduce((a,t)=>a+(hay.includes(t)?1:0),0);if(n>bestN){bestN=n;best={l,c}}}if(!best||bestN<1)return'Μπορώ να βοηθήσω σε θέματα όπως οικοσυστήματα, είδη, Ποσειδωνία, χελώνες, ρύπανση, μικροπλαστικά, κλιματική αλλαγή, βιώσιμη αλιεία, προσβάσιμες παραλίες και δράσεις πολιτών. Δοκίμασε να μου δώσεις μία λέξη-κλειδί.';let c=best.c,l=best.l,action=c.action?`<br><br><b>Μικρό επόμενο βήμα:</b> ${esc(c.action)}`:'';return`<b>${esc(l.title)}</b><br>${esc(c.text||l.summary||'')}${action}<br><br><button class="btn q" data-l="${l.id}" onclick="document.querySelector('#lesson')?.close?.();openLesson('${l.id}')">Άνοιξε την ενότητα →</button>`}

field=function(){$('#main').innerHTML=`${preview()}${hero('field','Από τη γνώση στη δράση','Μικρές πράξεις. Μεγάλη συμμετοχή.','Δράσεις με σαφείς ρόλους, πληροφορίες προσβασιμότητας και επιλογές συμμετοχής ώστε κάθε άνθρωπος να μπορεί να συνεισφέρει.','<div class="ba-glass"><small>Επόμενες δράσεις</small><strong>${S.events.length}</strong></div><div class="ba-glass"><small>Στόχος</small><strong style="font-size:1rem">Συμμετοχή χωρίς εμπόδια</strong></div>')}${sec('Προγραμματισμένες δράσεις','Επίλεξε τη μορφή συμμετοχής που σου ταιριάζει.')}<div class="ba-actions">${S.events.map(e=>`<article class="card ba-action"><div class="ba-thumb" style="background-image:url('${v('field')}')"></div><div class="ba-card-body"><span class="tag">${e.starts_at?new Date(e.starts_at).toLocaleDateString('el-GR'):'Δράση'}</span><h3>${esc(e.title)}</h3><p>${esc(e.description||'Συμμετοχική περιβαλλοντική δράση BlueAbility.')}</p><div class="ba-meta"><span>📍 ${esc(e.location||'Θα ανακοινωθεί')}</span>${e.capacity?`<span>👥 έως ${e.capacity}</span>`:''}</div><label style="font-size:.7rem">Ρόλος συμμετοχής<select data-rolechoice="${e.id}"><option>Συμμετέχω στη δράση</option><option>Παρατηρώ / καταγράφω</option><option>Υποστήριξη ομάδας</option><option>Φωτογραφική τεκμηρίωση</option></select></label><button class="btn p" data-j="${e.id}" style="margin-top:10px">Δήλωση συμμετοχής</button></div></article>`).join('')||'<article class="card ba-empty"><span class="ico">🌱</span><h3>Νέες δράσεις σύντομα</h3><p>Μπορείς στο μεταξύ να ολοκληρώσεις την ενότητα «Από τη γνώση στη δράση».</p></article>'}</div>${sec('Μπορείς να δράσεις και σήμερα','Τρεις μικρές ιδέες που δεν απαιτούν ειδικό εξοπλισμό.')}<div class="ba-grid ba-grid-3"><article class="card ba-panel"><h3>🔎 Παρατήρηση ακτής</h3><p class="muted">Κατέγραψε 5 στοιχεία που δείχνουν υγιές περιβάλλον και 3 πιέσεις.</p></article><article class="card ba-panel"><h3>♻️ Πρόληψη απορριμμάτων</h3><p class="muted">Διάλεξε ένα πλαστικό μίας χρήσης που μπορείς να μειώσεις αυτή την εβδομάδα.</p></article><article class="card ba-panel"><h3>💬 Μοιράσου τη γνώση</h3><p class="muted">Πες σε ένα άτομο κάτι καινούριο που έμαθες για τη θάλασσα.</p></article></div>`;$$('[data-j]').forEach(b=>b.onclick=async()=>{let choice=$(`[data-rolechoice="${b.dataset.j}"]`)?.value||'Συμμετοχή';if(isDemo())return toast('Η δήλωση ολοκληρώθηκε στην προεπισκόπηση.');let{error}=await sb.from('field_registrations').upsert({event_id:b.dataset.j,user_id:S.user.id,role_choice:choice},{onConflict:'event_id,user_id'});toast(error?error.message:'Η συμμετοχή σου καταχωρήθηκε.')})};

const community=async function(){let posts=[];if(!isDemo()){let{data}=await sb.from('community_posts').select('*').order('created_at',{ascending:false}).limit(30);posts=data||[]}else posts=[{id:'p1',author_name:'Μαρία',author_role:'Εκπαιδευτικός',body:'Η ομάδα μας ολοκλήρωσε σήμερα παρατήρηση ακτής. Το πιο ενδιαφέρον ήταν ότι οι μαθητές εντόπισαν μόνοι τους πηγές απορριμμάτων.',created_at:new Date(Date.now()-7200000).toISOString()},{id:'p2',author_name:'Νίκος',author_role:'Μαθητής',body:'Έμαθα ότι η Ποσειδωνία δεν είναι φύκι αλλά θαλάσσιο φυτό. Την επόμενη φορά θα προσπαθήσω να την αναγνωρίσω από την ακτή.',created_at:new Date(Date.now()-86400000).toISOString()}];$('#main').innerHTML=`${preview()}${hero('field','Κοινότητα BlueAbility','Μαθαίνουμε ο ένας από τον άλλον.','Μοιράσου μια παρατήρηση, μια ιδέα δράσης ή κάτι που έμαθες. Χωρίς βαθμολογίες δημοφιλίας και χωρίς δημόσια κατάταξη.','<div class="ba-glass"><small>Κανόνας κοινότητας</small><strong style="font-size:1rem">Σεβασμός · ασφάλεια · ιδιωτικότητα</strong></div>')}<div class="ba-community" style="margin-top:18px"><article class="card ba-compose"><h3>Νέα δημοσίευση</h3><p class="muted">Μην δημοσιεύεις προσωπικά στοιχεία, τηλέφωνα ή ακριβείς τοποθεσίες παιδιών.</p><form id="postForm"><textarea class="ba-note" name="body" maxlength="1000" placeholder="Τι έμαθες ή τι θέλεις να μοιραστείς;" required></textarea><button class="btn p" style="margin-top:10px">Δημοσίευση</button></form></article><section><h2 style="margin-top:0">Τελευταίες ιστορίες</h2>${posts.map(p=>`<article class="card ba-post"><div class="ba-post-head"><div class="ba-author"><span class="ba-avatar">${esc((p.author_name||'?')[0])}</span><div><b>${esc(p.author_name)}</b><small>${esc(p.author_role||'Μέλος')} · ${new Date(p.created_at).toLocaleDateString('el-GR')}</small></div></div>${!isDemo()&&(p.user_id===S.user.id||isAdmin())?`<button class="btn q" data-delpost="${p.id}">Διαγραφή</button>`:''}</div><p>${esc(p.body)}</p></article>`).join('')||'<article class="card ba-empty"><p>Γίνε ο πρώτος που θα μοιραστεί μια ιδέα.</p></article>'}</section></div>`;$('#postForm').onsubmit=async e=>{e.preventDefault();let body=new FormData(e.target).get('body').trim();if(isDemo())return toast('Η δημοσίευση έμεινε στην προεπισκόπηση.');let{error}=await sb.from('community_posts').insert({user_id:S.user.id,author_name:viewerName(),author_role:viewerLabel(),body});if(error)toast(error.message);else{toast('Δημοσιεύτηκε.');community()}};$$('[data-delpost]').forEach(b=>b.onclick=async()=>{if(!confirm('Να διαγραφεί η δημοσίευση;'))return;let{error}=await sb.from('community_posts').delete().eq('id',b.dataset.delpost);toast(error?error.message:'Η δημοσίευση διαγράφηκε.');if(!error)community()})};

progress=async function(){
 if(role()==='caregiver')return caregiverProgress();if(role()==='educator')return educatorReports();if(role()==='org_admin'&&!isDemo())return adminAnalytics();
 let p=pct();let gamesData=[];if(!isDemo()&&role()==='learner'){let{data}=await sb.from('game_results').select('game_slug,score,created_at').eq('learner_id',S.user.id).order('created_at',{ascending:false}).limit(20);gamesData=data||[]}
 $('#main').innerHTML=`${preview()}${hero('coast','Η διαδρομή σου','Η πρόοδος είναι δική σου.','Βλέπεις τι ολοκλήρωσες, τι θέλεις να ξαναδείς και ποια δραστηριότητα σε περιμένει — χωρίς σύγκριση με άλλους.','<div class="ba-glass"><small>Συνολική πρόοδος</small><strong>'+p+'%</strong></div><div class="ba-glass"><small>Ολοκληρώθηκαν</small><strong>'+done()+' / '+S.lessons.length+'</strong></div>')}${sec('Ανά ενότητα','Μπορείς να επιστρέψεις σε οποιαδήποτε ενότητα όσες φορές θέλεις.')}<div class="lessons ba-grid ba-grid-3">${cards(S.lessons)}</div>${sec('Παιχνίδια','Τα πιο πρόσφατα αποτελέσματα είναι προσωπικά και δεν εμφανίζονται σε leaderboard.')}<div class="ba-grid ba-grid-3">${gamesData.slice(0,6).map(g=>`<article class="card ba-panel"><span class="tag">${esc(GAME_DEFS.find(x=>x.slug===g.game_slug)?.title||g.game_slug)}</span><h3>${Math.round(+g.score||0)}%</h3><small class="muted">${new Date(g.created_at).toLocaleDateString('el-GR')}</small></article>`).join('')||'<article class="card ba-empty"><p>Παίξε ένα από τα 6 παιχνίδια για να εμφανιστεί εδώ το αποτέλεσμα.</p><button class="btn p" data-go="games">Παιχνίδια →</button></article>'}</div>`;bindLessons();bindPro()};

classroom=async function(){
 if(role()==='learner')return learnerClassroom();
 if(role()!=='educator')return $('#main').innerHTML=preview()+'<article class="card ba-empty"><p>Οι τάξεις είναι διαθέσιμες σε μαθητές και εκπαιδευτικούς.</p></article>';
 let classes=[],assign=[];
 if(isDemo()){classes=[{id:'demo1',name:'Τμήμα Θάλασσα Α',join_code:'SEA-A1',members:10},{id:'demo2',name:'Ομάδα Παράκτιας Δράσης',join_code:'COAST-7',members:8}];assign=[{title:'Η Ποσειδωνία',due_at:new Date(Date.now()+5*86400000).toISOString()},{title:'Σχέδιο καθαρής ακτής',due_at:new Date(Date.now()+9*86400000).toISOString()}]}else{let{data:c}=await sb.from('classrooms').select('id,name,join_code').eq('educator_id',S.user.id);classes=c||[];for(let cl of classes){let{count}=await sb.from('classroom_members').select('*',{count:'exact',head:true}).eq('classroom_id',cl.id);cl.members=count||0}let{data:a}=await sb.from('assignments').select('id,title,due_at,classroom_id,classrooms(name)').eq('created_by',S.user.id).order('created_at',{ascending:false});assign=a||[]}
 $('#main').innerHTML=`${preview()}${hero('educator','Εκπαιδευτικός χώρος','Οργάνωσε μάθηση που χωρά όλους.','Δημιούργησε τάξεις, μοίρασε ενότητες, δες την πρόοδο και χρησιμοποίησε τις δραστηριότητες με τον ρυθμό της ομάδας σου.','<div class="ba-glass"><small>Τάξεις</small><strong>'+classes.length+'</strong></div><div class="ba-glass"><small>Συμμετέχοντες</small><strong>'+classes.reduce((a,c)=>a+(c.members||0),0)+'</strong></div>')}${sec('Οι τάξεις σου','Ο κωδικός συμμετοχής μπορεί να δοθεί στους μαθητές.','<button class="btn p" id="newClass">+ Νέα τάξη</button>')}<div class="ba-grid ba-grid-2">${classes.map(c=>`<article class="card ba-class"><div class="ba-class-cover" style="background-image:url('${v('educator')}')"></div><div class="ba-class-body"><span class="ba-code">${esc(c.join_code)}</span><h3>${esc(c.name)}</h3><p class="muted">${c.members||0} μέλη</p><button class="btn q" data-openclass="${c.id}">Μέλη & αναθέσεις →</button></div></article>`).join('')||'<article class="card ba-empty"><p>Δημιούργησε την πρώτη σου τάξη.</p></article>'}</div>${sec('Πρόσφατες αναθέσεις','Σύνδεσε μια εκπαιδευτική ενότητα με σαφείς οδηγίες.')}<div class="ba-grid ba-grid-2">${assign.slice(0,6).map(a=>`<article class="card ba-panel"><span class="tag">${esc(a.classrooms?.name||'Τάξη')}</span><h3>${esc(a.title)}</h3><small class="muted">${a.due_at?'Έως '+new Date(a.due_at).toLocaleDateString('el-GR'):'Χωρίς προθεσμία'}</small></article>`).join('')||'<article class="card ba-empty"><p>Δεν υπάρχουν ακόμη αναθέσεις.</p></article>'}</div>`;
 $('#newClass').onclick=async()=>{if(isDemo())return toast('Στην προεπισκόπηση δεν δημιουργούνται πραγματικές τάξεις.');let name=prompt('Όνομα νέας τάξης');if(!name)return;let{error}=await sb.from('classrooms').insert({organization_id:S.m.organization_id,name,educator_id:S.user.id});toast(error?error.message:'Η τάξη δημιουργήθηκε.');if(!error)classroom()};$$('[data-openclass]').forEach(b=>b.onclick=()=>openClass(b.dataset.openclass,classes.find(c=>c.id===b.dataset.openclass)))};
async function learnerClassroom(){let classes=[],assign=[];if(!isDemo()){let{data:m}=await sb.from('classroom_members').select('classroom_id,classrooms(id,name,join_code)').eq('learner_id',S.user.id);classes=(m||[]).map(x=>x.classrooms).filter(Boolean);if(classes.length){let{data:a}=await sb.from('assignments').select('id,title,instructions,due_at,classroom_id,lessons(id,title)').in('classroom_id',classes.map(x=>x.id)).order('created_at',{ascending:false});assign=a||[]}}else{classes=[{id:'d1',name:'Τμήμα Θάλασσα Α',join_code:'SEA-A1'}];assign=[{id:'a1',title:'Η Ποσειδωνία',instructions:'Ολοκλήρωσε την ενότητα και γράψε μία παρατήρηση.',due_at:new Date(Date.now()+5*86400000).toISOString(),lessons:S.lessons.find(x=>x.slug==='posidonia')}]}$('#main').innerHTML=`${preview()}${hero('educator','Η τάξη μου','Μαθαίνουμε μαζί.','Συνδέσου στην τάξη σου με τον κωδικό που έδωσε ο εκπαιδευτικός και δες τις αναθέσεις σου.','<div class="ba-glass"><small>Τάξεις</small><strong>'+classes.length+'</strong></div><div class="ba-glass"><small>Αναθέσεις</small><strong>'+assign.length+'</strong></div>')}<article class="card ba-panel" style="margin-top:18px"><h3>Σύνδεση σε τάξη</h3><form id="joinClass" style="display:flex;gap:9px;flex-wrap:wrap"><input name="code" placeholder="Κωδικός τάξης" required style="flex:1;min-width:180px"><button class="btn p">Σύνδεση</button></form></article>${sec('Οι τάξεις μου')}<div class="ba-grid ba-grid-2">${classes.map(c=>`<article class="card ba-panel"><span class="ba-code">${esc(c.join_code)}</span><h3>${esc(c.name)}</h3></article>`).join('')||'<article class="card ba-empty"><p>Δεν έχεις συνδεθεί ακόμη σε τάξη.</p></article>'}</div>${sec('Αναθέσεις')}<div class="ba-grid ba-grid-2">${assign.map(a=>`<article class="card ba-panel"><span class="tag">Ανάθεση</span><h3>${esc(a.title)}</h3><p class="muted">${esc(a.instructions||'')}</p><small>${a.due_at?'Έως '+new Date(a.due_at).toLocaleDateString('el-GR'):''}</small>${a.lessons?.id?`<br><br><button class="btn p" data-l="${a.lessons.id}">Άνοιξε ενότητα →</button>`:''}</article>`).join('')||'<article class="card ba-empty"><p>Δεν υπάρχουν αναθέσεις.</p></article>'}</div>`;$('#joinClass').onsubmit=async e=>{e.preventDefault();let code=new FormData(e.target).get('code');if(isDemo())return toast('Στην προεπισκόπηση η τάξη φαίνεται ήδη συνδεδεμένη.');let{data,error}=await sb.rpc('join_classroom_by_code',{p_code:code});toast(error?error.message:'Συνδέθηκες στην τάξη '+(data?.[0]?.classroom_name||''));if(!error)learnerClassroom()};bindLessons()}
async function openClass(id,c){if(isDemo())return toast('Στην προεπισκόπηση εμφανίζονται ενδεικτικά μέλη και αναθέσεις.');let[{data:m},{data:a}]=await Promise.all([sb.from('classroom_members').select('learner_id,profiles(id,display_name,email)').eq('classroom_id',id),sb.from('assignments').select('id,title,instructions,due_at,lessons(id,title)').eq('classroom_id',id).order('created_at',{ascending:false})]);$('#main').innerHTML=`<div class="head"><div><p class="eye">Τάξη</p><h1>${esc(c?.name||'Τάξη')}</h1><p>Κωδικός: <span class="ba-code">${esc(c?.join_code||'')}</span></p></div><button class="btn p" id="newAssignment">+ Νέα ανάθεση</button></div>${sec('Μέλη')}<div class="card ba-panel"><table class="ba-table"><thead><tr><th>Όνομα</th><th>Email</th></tr></thead><tbody>${(m||[]).map(x=>`<tr><td>${esc(x.profiles?.display_name||'Μέλος')}</td><td>${esc(x.profiles?.email||'')}</td></tr>`).join('')||'<tr><td colspan="2">Δεν υπάρχουν ακόμη μέλη.</td></tr>'}</tbody></table></div>${sec('Αναθέσεις')}<div class="ba-grid ba-grid-2">${(a||[]).map(x=>`<article class="card ba-panel"><h3>${esc(x.title)}</h3><p class="muted">${esc(x.instructions||'')}</p><small>${x.due_at?new Date(x.due_at).toLocaleDateString('el-GR'):''}</small></article>`).join('')||'<article class="card ba-empty"><p>Καμία ανάθεση.</p></article>'}</div>`;$('#newAssignment').onclick=async()=>{let title=prompt('Τίτλος ανάθεσης');if(!title)return;let lessonTitle=prompt('Γράψε μέρος του τίτλου της ενότητας (προαιρετικό)')||'';let lesson=lessonTitle?S.lessons.find(x=>x.title.toLowerCase().includes(lessonTitle.toLowerCase())):null;let instructions=prompt('Σύντομες οδηγίες')||'';let{error}=await sb.from('assignments').insert({classroom_id:id,lesson_id:lesson?.id||null,title,instructions,created_by:S.user.id});toast(error?error.message:'Η ανάθεση δημιουργήθηκε.');if(!error)openClass(id,c)}}

async function educatorHome(){let classes=[],assign=[];if(!isDemo()){let{data:c}=await sb.from('classrooms').select('id,name,join_code').eq('educator_id',S.user.id);classes=c||[];let{data:a}=await sb.from('assignments').select('id,title,due_at').eq('created_by',S.user.id);assign=a||[]}else{classes=[{id:'1'},{id:'2'}];assign=[{}, {}, {}, {}]}let members=0;if(!isDemo())for(let c of classes){let{count}=await sb.from('classroom_members').select('*',{count:'exact',head:true}).eq('classroom_id',c.id);members+=count||0}else members=18;$('#main').innerHTML=`${preview()}${hero('educator','Εκπαιδευτικός','Καλωσόρισες στην τάξη της θάλασσας.','Έτοιμο υλικό, προσβάσιμες δραστηριότητες, τάξεις, αναθέσεις και αναφορές — ώστε ο χρόνος σου να πηγαίνει στους ανθρώπους, όχι στην προετοιμασία.','<div class="ba-glass"><small>Τάξεις</small><strong>'+classes.length+'</strong></div><div class="ba-glass"><small>Μαθητές / ωφελούμενοι</small><strong>'+members+'</strong></div>')}<div class="ba-stats">${stat('👥',members,'συμμετέχοντες')}${stat('📚',S.lessons.length,'έτοιμες ενότητες')}${stat('🧩','6','παιχνίδια')}${stat('📝',assign.length,'αναθέσεις')}</div>${sec('Γρήγορες ενέργειες')}<div class="ba-grid ba-grid-3"><article class="card ba-panel"><h3>👥 Διαχείριση τάξεων</h3><p class="muted">Κωδικοί, μέλη και αναθέσεις.</p><button class="btn p" data-go="classroom">Άνοιξε τάξεις</button></article><article class="card ba-panel"><h3>📘 Εκπαιδευτική βιβλιοθήκη</h3><p class="muted">18 θεματικές διαδρομές σε 3 επίπεδα.</p><button class="btn q" data-go="learn">Άνοιξε βιβλιοθήκη</button></article><article class="card ba-panel"><h3>📊 Αναφορές</h3><p class="muted">Δες πρόοδο χωρίς δημόσιες συγκρίσεις.</p><button class="btn q" data-go="progress">Άνοιξε αναφορές</button></article></div>`;bindPro()}
async function caregiverHome(){let links=[];if(!isDemo()){let{data}=await sb.from('caregiver_links').select('learner_id,approved_at,profiles!caregiver_links_learner_id_fkey(display_name,email)').eq('caregiver_id',S.user.id);links=data||[]}else links=[{learner_id:'demo',approved_at:new Date().toISOString(),profiles:{display_name:'Ελένη',email:'demo'}}];$('#main').innerHTML=`${preview()}${hero('family','Οικογένεια / φροντιστής','Μαζί στη θάλασσα.','Χρήσιμες πληροφορίες, εικόνα προόδου και πρακτικές ιδέες ώστε η μάθηση να συνεχίζεται με ασφάλεια και χωρίς πίεση.','<div class="ba-glass"><small>Συνδεδεμένοι μαθητές</small><strong>'+links.filter(x=>x.approved_at).length+'</strong></div><div class="ba-glass"><small>Επόμενο βήμα</small><strong style="font-size:1rem">Μια κοινή δραστηριότητα</strong></div>')}<article class="card ba-panel" style="margin-top:18px"><h3>Σύνδεση με μαθητή / ωφελούμενο</h3><p class="muted">Γράψε το email του λογαριασμού. Ο ίδιος ο μαθητής/ωφελούμενος θα εγκρίνει τη σύνδεση.</p><form id="careLink" style="display:flex;gap:9px;flex-wrap:wrap"><input name="email" type="email" placeholder="Email μαθητή" required style="flex:1"><button class="btn p">Αποστολή αιτήματος</button></form></article>${sec('Οι συνδέσεις μου')}<div class="ba-grid ba-grid-2">${links.map(x=>`<article class="card ba-panel"><span class="tag">${x.approved_at?'Ενεργή σύνδεση':'Αναμονή έγκρισης'}</span><h3>${esc(x.profiles?.display_name||'Μαθητής / ωφελούμενος')}</h3><p class="muted">${x.approved_at?'Μπορείς να δεις την πρόοδο και να υποστηρίξεις τη διαδρομή.':'Το αίτημα έχει σταλεί.'}</p></article>`).join('')||'<article class="card ba-empty"><p>Δεν υπάρχει ακόμη σύνδεση.</p></article>'}</div>${sec('Ιδέες για το σπίτι')}<div class="ba-grid ba-grid-3"><article class="card ba-panel"><h3>🗣️ Ρώτησε, μην εξετάζεις</h3><p class="muted">«Ποιο ήταν το πιο ενδιαφέρον που είδες σήμερα;»</p></article><article class="card ba-panel"><h3>🌊 Μικρή παρατήρηση</h3><p class="muted">Σε μια βόλτα στην ακτή, βρείτε μαζί 3 στοιχεία ζωής.</p></article><article class="card ba-panel"><h3>⏸️ Χωρίς πίεση</h3><p class="muted">Η επανάληψη είναι μέρος της μάθησης. Δεν χρειάζεται ταχύτητα.</p></article></div>`;$('#careLink').onsubmit=async e=>{e.preventDefault();if(isDemo())return toast('Το αίτημα εμφανίζεται μόνο στην προεπισκόπηση.');let email=new FormData(e.target).get('email');let{error}=await sb.rpc('request_caregiver_link_by_email',{p_email:email});toast(error?error.message:'Το αίτημα σύνδεσης στάλθηκε.');if(!error)caregiverHome()}}
async function caregiverProgress(){let links=[];if(!isDemo()){let{data}=await sb.from('caregiver_links').select('learner_id,approved_at,profiles!caregiver_links_learner_id_fkey(display_name)').eq('caregiver_id',S.user.id).not('approved_at','is',null);links=data||[]}else links=[{learner_id:'demo',profiles:{display_name:'Ελένη'}}];let blocks=[];for(let l of links){let prs=[];if(!isDemo()){let{data}=await sb.from('lesson_progress').select('lesson_id,mastery,completed').eq('learner_id',l.learner_id);prs=data||[]}else prs=S.lessons.slice(0,6).map((x,i)=>({lesson_id:x.id,mastery:[100,100,80,60,30,0][i],completed:i<2}));let avg=prs.length?Math.round(prs.reduce((a,x)=>a+(+x.mastery||0),0)/S.lessons.length):0;blocks.push(`<article class="card ba-panel"><div style="display:flex;align-items:center;justify-content:space-between;gap:15px"><div><span class="tag">Πρόοδος</span><h3>${esc(l.profiles?.display_name||'Μαθητής')}</h3><p class="muted">${prs.filter(x=>x.completed).length} ολοκληρωμένες ενότητες</p></div><div class="ba-kpi-ring" style="--pct:${avg}%"><strong>${avg}%</strong></div></div></article>`)}$('#main').innerHTML=`${preview()}${hero('family','Υποστηρικτική εικόνα προόδου','Πρόοδος χωρίς σύγκριση.','Βλέπεις τη διαδρομή του συνδεδεμένου μαθητή ώστε να ενθαρρύνεις, όχι να πιέζεις.','<div class="ba-glass"><small>Συνδέσεις</small><strong>'+links.length+'</strong></div>')}${sec('Συνδεδεμένοι μαθητές') }<div class="ba-grid ba-grid-2">${blocks.join('')||'<article class="card ba-empty"><p>Χρειάζεται πρώτα εγκεκριμένη σύνδεση με μαθητή/ωφελούμενο.</p></article>'}</div>`}
async function educatorReports(){let{data:cls}=isDemo()?{data:[{id:'d'}]}:await sb.from('classrooms').select('id,name').eq('educator_id',S.user.id);let ids=(cls||[]).map(x=>x.id),members=[];if(isDemo())members=Array.from({length:18},(_,i)=>({learner_id:'d'+i}));else if(ids.length){let{data}=await sb.from('classroom_members').select('learner_id,profiles(display_name)').in('classroom_id',ids);members=data||[]}let prs=[];if(!isDemo()&&members.length){let{data}=await sb.from('lesson_progress').select('learner_id,mastery,completed').in('learner_id',members.map(x=>x.learner_id));prs=data||[]}let avg=isDemo()?72:prs.length?Math.round(prs.reduce((a,x)=>a+(+x.mastery||0),0)/prs.length):0;$('#main').innerHTML=`${preview()}${hero('educator','Αναφορές εκπαιδευτικού','Βλέπε τάσεις, όχι κατατάξεις.','Η αναφορά δείχνει πού χρειάζεται υποστήριξη η ομάδα χωρίς δημόσιο leaderboard ή τιμωρητικούς δείκτες.','<div class="ba-glass"><small>Συμμετέχοντες</small><strong>'+members.length+'</strong></div><div class="ba-glass"><small>Μέση mastery</small><strong>'+avg+'%</strong></div>')}<div class="ba-stats">${stat('👥',members.length,'συμμετέχοντες')}${stat('📈',avg+'%','μέση mastery')}${stat('📘',S.lessons.length,'ενότητες')}${stat('🎮','6','παιχνίδια')}</div>${sec('Παιδαγωγική χρήση','Χρησιμοποίησε τα δεδομένα ως ένδειξη για επανάληψη και υποστήριξη, όχι ως βαθμολογική κατάταξη.')}<article class="card ba-panel"><h3>Προτεινόμενες επόμενες κινήσεις</h3><div class="ba-checks"><div class="ba-check"><b>✓</b><span>Επανάλαβε μία έννοια με διαφορετικό μέσο: εικόνα, ακρόαση ή παιχνίδι.</span></div><div class="ba-check"><b>✓</b><span>Δώσε επιλογή ανάμεσα σε ατομική και ομαδική δραστηριότητα.</span></div><div class="ba-check"><b>✓</b><span>Σύνδεσε μια ψηφιακή ενότητα με μικρή δράση στο φυσικό περιβάλλον.</span></div></div></article>`}
async function adminAnalytics(){let[{count:u},{count:lp},{count:gr},{count:cp}]=await Promise.all([sb.from('profiles').select('*',{count:'exact',head:true}),sb.from('lesson_progress').select('*',{count:'exact',head:true}),sb.from('game_results').select('*',{count:'exact',head:true}),sb.from('community_posts').select('*',{count:'exact',head:true})]);$('#main').innerHTML=`${hero('hero','BlueAbility Analytics','Η πλατφόρμα σε πραγματική χρήση.','Σύνοψη δραστηριότητας χωρίς δημόσιες κατατάξεις και χωρίς να αλλάζει ο ρόλος των χρηστών.','<div class="ba-glass"><small>Χρήστες</small><strong>'+(u||0)+'</strong></div><div class="ba-glass"><small>Μαθησιακές εγγραφές</small><strong>'+(lp||0)+'</strong></div>')}<div class="ba-stats">${stat('👤',u||0,'λογαριασμοί')}${stat('📘',lp||0,'εγγραφές προόδου')}${stat('🎮',gr||0,'ολοκληρώσεις παιχνιδιών')}${stat('☁',cp||0,'δημοσιεύσεις κοινότητας')}</div>${sec('Περιεχόμενο')}<div class="ba-grid ba-grid-3">${S.lessons.slice(0,6).map(l=>`<article class="card ba-panel"><span class="tag">${String(l.position).padStart(2,'0')}</span><h3>${esc(l.title)}</h3><p class="muted">${esc(l.summary||'')}</p></article>`).join('')}</div>`}

organization=async function(){if(role()!=='org_admin'||isDemo())return adminAnalytics();let[{count:m},{count:c},{data:users},{count:posts}]=await Promise.all([sb.from('organization_memberships').select('*',{count:'exact',head:true}).eq('organization_id',S.m.organization_id),sb.from('classrooms').select('*',{count:'exact',head:true}).eq('organization_id',S.m.organization_id),sb.from('profiles').select('id,display_name,email,requested_account_type,email_confirmed,created_at').order('created_at',{ascending:false}),sb.from('community_posts').select('*',{count:'exact',head:true})]);let publicUsers=(users||[]).filter(x=>x.requested_account_type!=='admin'),educators=publicUsers.filter(x=>x.requested_account_type==='educator').length,learners=publicUsers.filter(x=>['student','beneficiary'].includes(x.requested_account_type)).length;$('#main').innerHTML=`${hero('hero','Διαχείριση BlueAbility','Ένας οργανισμός, πολλοί διαφορετικοί δρόμοι μάθησης.','Οι νέοι λογαριασμοί ενεργοποιούνται αυτόματα με τον ρόλο που επιλέγουν. Εσύ παραμένεις ο μοναδικός διαχειριστής.','<div class="ba-glass"><small>Μέλη</small><strong>'+(m||0)+'</strong></div><div class="ba-glass"><small>Τάξεις</small><strong>'+(c||0)+'</strong></div>')}<div class="ba-stats">${stat('👥',learners,'μαθητές / ωφελούμενοι')}${stat('🧑‍🏫',educators,'εκπαιδευτικοί')}${stat('🏫',c||0,'τάξεις')}${stat('☁',posts||0,'δημοσιεύσεις')}</div>${sec('Χρήστες BlueAbility','Ρόλοι από την εγγραφή — χωρίς ουρά έγκρισης.')}<div class="card ba-panel"><table class="ba-table"><thead><tr><th>Όνομα</th><th>Ρόλος</th><th>Email</th><th>Εγγραφή</th></tr></thead><tbody>${publicUsers.map(x=>`<tr><td><b>${esc(x.display_name||'Χωρίς όνομα')}</b></td><td>${esc(accountLabels[x.requested_account_type]||'Χρήστης')}</td><td>${esc(x.email||'')}${x.email_confirmed?' ✓':''}</td><td>${new Date(x.created_at).toLocaleDateString('el-GR')}</td></tr>`).join('')||'<tr><td colspan="4">Δεν υπάρχουν ακόμη χρήστες.</td></tr>'}</tbody></table></div>`};

function bindPro(){bindLessons();$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-play]').forEach(b=>b.onclick=()=>startGame(b.dataset.play))}

document.addEventListener('click',e=>{let b=e.target.closest('[data-play]');if(b){e.preventDefault();startGame(b.dataset.play)}},true);
upgradeShell();
// Re-render current view after this enhancement layer is loaded.
setTimeout(()=>{if(typeof S!=='undefined'&&S.user){renderNav();go(S.view||'home')}},0);
})();
